"""Gera os dois relatórios PDF da Sprint 3. Requer Python + reportlab."""
from pathlib import Path
from xml.sax.saxutils import escape
import json
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak, Preformatted
from reportlab.lib import colors
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.enums import TA_LEFT
from reportlab.lib.pagesizes import A4

ROOT = Path(__file__).resolve().parents[2]
styles = getSampleStyleSheet()
styles.add(ParagraphStyle(name='BodyDS',fontName='Helvetica',fontSize=10,leading=15,spaceAfter=9,textColor=colors.HexColor('#292929')))
styles.add(ParagraphStyle(name='SmallDS',fontName='Helvetica',fontSize=8,leading=11,spaceAfter=6))
styles.add(ParagraphStyle(name='CodeDS',fontName='Courier',fontSize=8,leading=11,backColor=colors.HexColor('#f0f0f0'),borderPadding=8,spaceAfter=14))
styles['Title'].fontSize=23;styles['Title'].leading=28;styles['Title'].textColor=colors.HexColor('#060640')
styles['Heading1'].fontSize=16;styles['Heading1'].leading=21;styles['Heading1'].textColor=colors.HexColor('#182467')
styles['Heading2'].fontSize=12;styles['Heading2'].leading=17

def p(text,style='BodyDS'): return Paragraph(text,styles[style])
def title(text,sub): return [p(text,'Title'),p(sub,'SmallDS'),Spacer(1,12)]
def heading(text): return p(text,'Heading1')
def table(rows,widths):
 data=[[p(escape(str(x)),'SmallDS') for x in row] for row in rows]
 t=Table(data,colWidths=widths,repeatRows=1,hAlign='LEFT')
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#e6eef4')),('VALIGN',(0,0),(-1,-1),'TOP'),('BOTTOMPADDING',(0,0),(-1,-1),7),('TOPPADDING',(0,0),(-1,-1),7),('LINEBELOW',(0,0),(-1,-1),.4,colors.HexColor('#d4dce4'))]))
 return t

def footer(canvas,doc):
 canvas.setFont('Helvetica',8);canvas.setFillColor(colors.HexColor('#666666'))
 canvas.drawString(44,27,'Projeto DS | Frequência UFPE | Sprint 3 | 11/11/2026')
 canvas.drawRightString(A4[0]-44,27,str(doc.page))
def build(path,story):
 SimpleDocTemplate(str(ROOT/path),pagesize=A4,rightMargin=44,leftMargin=44,topMargin=42,bottomMargin=48,title=path.stem,author='Projeto DS - Frequência UFPE').build(story,onFirstPage=footer,onLaterPages=footer)

m=json.loads((ROOT/'docs/testes/indicadores.json').read_text())
s=title('Suíte de testes e análise crítica','Sprint 3 - Parte 1 | Frontend em modo demonstração')
s += [heading('1. Contexto e escopo'),p('O sistema permite ao professor abrir uma chamada com código temporário e ao aluno registrar presença. Foram selecionadas cinco histórias de trabalho: abertura, registro, frequência, tempo restante e persistência. Os rótulos US01-US05 foram criados nesta atividade; a equipe ainda deve reconciliá-los com o backlog da Sprint 2. A persistência (US05) é suporte técnico ao fluxo.'),p('Stack: React 18, TypeScript 5.9 e Vite 7. Ferramentas: Vitest 3.2.4 e @vitest/coverage-v8 3.2.4, ambiente Node. Geração: ChatGPT/Codex, família GPT-6 informada pelo ambiente, em 11/11/2026; snapshot interno não exposto. '),p('A medição inclui attendance.ts e summary.ts, que concentravam as regras e a persistência antes das três novas refatorações. Não mede o backend, autenticação, componentes React nem toda a aplicação.'),heading('2. Projeto dos casos e limite do protocolo'),p('A matriz inicial contém <b>14 critérios, 32 partições e 18 pontos-limite</b>. Exemplo: duração 1 e 120 aceita; 0 e 121 rejeitada. O registro é válido 1 ms antes de expiresAt e inválido no instante de expiração e 1 ms depois. CT24/CT25 verificam fronteiras de segundo, minuto e zero.'),p('<b>Nota metodológica:</b> a matriz foi elaborada com apoio de IA e registrada antes dos testes no mesmo contexto de geração. Não constitui preparação manual independente nem experimento cego. Essa diferença em relação ao roteiro deve ser validada com a docente; o procedimento está detalhado no log.'),p('Os critérios foram reconstruídos do escopo acordado e de contratos atuais. As escolhas de 1-120 minutos, arredondamento e tratamento de erro de armazenamento precisam de ratificação. Essa limitação impede tratar cobertura de requisitos como validação independente de todos os requisitos originais.'),PageBreak()]
s+= [heading('3. Geração e execução'),p('A v1 foi produzida em uma rodada e preservada sem alterações: 44 casos executaram e passaram, sem erro de carregamento. A resposta integral, instrução de geração registrada pelo assistente, contexto e SHA-256 estão em docs/testes. Não houve rodadas adicionais para corrigir imports. A v2 copia os 44 casos e acrescenta seis casos para lacunas observadas.'),p('Vitest transpila os testes; ausência de erro de carregamento não é prova de tipagem. Um comando separado, npm run check, verifica os tipos do app e dos testes. O build é outra verificação separada.'),heading('4. Indicadores no mesmo código'),table([
['Indicador','v1','v2'],['Gerados / passaram / falharam / não carregaram','44 / 44 / 0 / 0','50 / 50 / 0 / 0'],['Linhas executadas','100%','100%'],['Branches executados','97,67%','100%'],['Critérios com ao menos um teste','13/14 = 92,86%','14/14 = 100%'],['Partições exercitadas','27/32 = 84,38%','32/32 = 100%'],['Pontos-limite exercitados','18/18 = 100%','18/18 = 100%'],['Sem asserção ou com apenas asserção trivial','0','0'],['Defeitos reais demonstrados por falha','0','0']], [283,112,112]),Spacer(1,14),p('Fontes: docs/testes/relatorios/v1/index.html e v2/index.html, seus coverage-summary.json, saídas v1-execucao.txt/v2-execucao.txt e matriz-final.md. As contagens funcionais vêm da inspeção dos testes e da matriz, não do V8. Cada critério conta se tem ao menos um cenário; isso não garante todas as combinações.'),p('Os relatórios v1 e v2 foram medidos antes de DT-01/02/03, com os mesmos arquivos e configuração. A medição pós-refatoração está separada em docs/qualidade/evidencias/cobertura-final. Mover arquivos altera denominadores; não misturamos essa medição com a comparação inicial.'),PageBreak()]
s += [heading('5. Análise crítica com evidências'),p('<b>Técnicas funcionais.</b> A v1 cobriu os 18 limites previstos, incluindo 0/1 e 120/121 minutos e o instante de expiração. Deixou cinco partições sem cenários controlados: CT07 (colisão), CT29 (sem locks), CT30 (JSON inválido), CT31 (callback falhando) e CT32 (falha ao salvar). A comparação com uma matriz manual independente não foi realizada, conforme a nota metodológica.'),p('<b>Requisitos.</b> US05-CA3 não tinha teste na v1. US01-CA3 já contava como coberto pelo formato e unicidade observada, mas faltava provocar uma colisão. Isso mostra a diferença entre 92,86% de critérios e 84,38% de partições. As duas suítes usam testes associados aos critérios desta matriz; a validade desses critérios ainda requer revisão humana.'),p('<b>Linhas versus branches.</b> A v1 executou 100% das linhas, mas deixou um ramo sem execução na linha 47 da versão original de attendance.ts:'),Preformatted('return navigator.locks\n  ? navigator.locks.request(storageKey, save)\n  : Promise.resolve().then(save)',styles['CodeDS']),p('CT28 percorreu o caminho com lock e verificou que leitura e escrita aconteciam enquanto o lock estava ativo. A mesma expressão ocupa uma linha coberta, mas o fallback não foi executado. CT29 cobre o outro caminho e verifica o conteúdo salvo e devolvido. O relatório V8 passa de 97,67% para 100% de branches, ganho de 2,33 pontos percentuais.'),p('<b>Oráculos.</b> Os testes comparam expiração exata, presença por aluno, rejeições, imutabilidade e percentuais com valores explícitos; a inspeção não encontrou teste sem asserção nem asserção apenas de existência. Entretanto quatro casos da v2 (CT30, duas variantes de CT31, CT32) caracterizam propagação de erro atual, não um critério aprovado independentemente pela equipe. Não foi observado teste passando e validando um defeito, mas isso não é prova de ausência de defeitos.'),p('Risco conhecido: JSON válido com estrutura errada não é validado por readCalls (DT-07). Locks simulados não provam comportamento concorrente real. Mensagens corretas e testes passando não demonstram autorização segura de alunos ou professores.'),PageBreak()]
s += [heading('6. Melhorias da v2'),table([['Lacuna','Caso acrescentado','Efeito'],['Colisão de código','CT07: gerador retorna ABC123 e depois 000102','Confirma repetição do sorteio e preservação do histórico'],['Fallback','CT29: navigator sem locks','Exercita branch ausente e verifica persistência'],['JSON inválido','CT30: leitura de {invalid','Caracteriza erro sem silenciosamente substituir dados'],['Falha de domínio','CT31 com lock e sem lock','Duas variantes; não chama setItem e mantém registros'],['Falha de gravação','CT32: setItem lança erro','Promise rejeita, sem sucesso falso']], [104,206,197]),Spacer(1,14),p('A v2 acrescentou seis casos para cinco partições e um critério ausente. Todos os limites já estavam na v1. As metas quantitativas desta matriz foram atingidas: 14/14 critérios, 32/32 partições, 18/18 limites e branches acima da v1. A suíte passou antes e após cada uma das três refatorações, sem mudar os testes para acomodar os novos arquivos.'),heading('7. Conclusão e próximos passos'),p('A LLM foi útil para acelerar casos repetitivos e explicitar fronteiras; a medição identificou um caminho estrutural ausente e a matriz expôs lacunas adicionais que 100% de linhas escondia. Usaríamos essa abordagem com critérios aprovados previamente, matriz humana independente, revisão de oráculos e preservação da resposta original. Uma suíte ampla continua sendo uma evidência parcial do comportamento.'),p('<b>Próximos passos:</b> validar histórias e critérios, revisar oráculos, registrar a revisão dos integrantes, distribuir o backlog e alinhar com a docente a diferença metodológica descrita na seção 2.'),heading('Apêndices no repositório'),p('docs/testes/matriz-inicial.md e matriz-final.md; llm-log.md; respostas/v1-resposta-integral.ts.txt e v2-resposta-integral.ts.txt; contexto/; indicadores.json; integridade-v1.sha256. Os testes ficam em p07-frontend/tests/v1-llm e tests/v2. O manual explica como reproduzir as medições históricas sem sobrescrevê-las.','SmallDS')]
build(Path('docs/testes/analise-critica.pdf'),s)

s=title('Relatório de refatoração','Sprint 3 - Parte 2 | Três pagamentos de dívida com testes antes e depois')
s += [p('Escopo: regras de presença e persistência do frontend de demonstração. A refatoração visual anterior não é contada como mudança protegida por esta suíte. A v2 com 50 testes foi concluída antes das mudanças abaixo; os mesmos testes foram executados após cada passo.'),heading('DT-01 - Constantes com significado'),p('<b>Diagnóstico:</b> limites de duração e conversões apareciam como literais. Categoria: Magic Numbers e integridade conceitual. Escolha: baixo risco e fronteiras já testadas.'),p('<b>Antes</b>'),Preformatted('minutes < 1 || minutes > 120\nnew Uint8Array(3)\nexpiresAt: now + minutes * 60_000',styles['CodeDS']),p('<b>Depois</b>'),Preformatted('minutes < MIN_CALL_MINUTES ||\n  minutes > MAX_CALL_MINUTES\nnew Uint8Array(CODE_BYTE_LENGTH)\nexpiresAt: now + minutes * MILLISECONDS_PER_MINUTE',styles['CodeDS']),p('<b>Catálogo:</b> Replace Magic Literal. Arquivo novo: src/modules/attendance/domain/constants.ts. Os valores permanecem 1, 120, 3, 1000 e 60; mensagens e conversões não mudaram. Não foi extraído todo literal incidental: base hexadecimal e padding continuam no algoritmo.'),p('<b>Evidência:</b> 50/50 antes, 50/50 depois, zero falhas. Logs: docs/qualidade/evidencias/antes-refatoracoes.txt e DT-01-depois.txt. Commit: “DT-01: substitui literais de validade e codigo por constantes”.'),p('Os arquivos de testes não foram alterados. As refatorações são fornecidas em commits separados; ao importar com git am, os hashes locais podem mudar, mas assuntos e sequência permanecem.'),PageBreak()]
s += [heading('DT-02 - Separação de tipos, dados e regras'),p('<b>Diagnóstico:</b> attendance.ts concentrava contratos TypeScript, alunos/turmas fictícios, persistência e operações de chamada. Categoria: baixa coesão e SRP. Escolha: separar responsabilidades mantendo a API pública já coberta.'),p('<b>Antes - um módulo</b>'),Preformatted('attendance.ts\n  type Call / Class / Student / Status\n  demoStudent / demoClasses\n  readCalls / updateCalls\n  openCall / register / timeLeft',styles['CodeDS']),p('<b>Depois deste passo</b>'),Preformatted('modules/attendance/domain/types.ts\nmodules/attendance/demoData.ts\nmodules/attendance/domain/rules.ts\nattendance.ts -> reexports + persistencia',styles['CodeDS']),p('<b>Catálogo:</b> Extract Module e Move Function. Tipos mudam por contrato; dados fictícios mudam por cenário; regras mudam por negócio. A fachada attendance.ts mantém os imports anteriores e evita alterar os consumidores durante a migração.'),p('<b>Limite:</b> register ainda importa demoClasses. A organização melhorou a coesão, mas não eliminou o acoplamento ao catálogo fictício; DT-04 permanece aberta. Não alegamos uma arquitetura de domínio independente completa.'),p('<b>Evidência:</b> 50/50 antes (DT-01-depois.txt), 50/50 depois (DT-02-depois.txt). Commit: “DT-02: separa tipos dados de demonstracao e regras de presenca”. Nenhuma mudança nos testes.'),PageBreak()]
s += [heading('DT-03 - Isolamento da persistência'),p('<b>Diagnóstico:</b> a fachada ainda implementava acesso ao navegador. Categoria: baixa coesão, SRP e acoplamento. Escolha: CT26-32 já protegiam leitura, gravação, locks, fallback e propagação de falhas.'),p('<b>Antes</b>'),Preformatted('attendance.ts\n  export const storageKey = ...\n  export function readCalls() { ... }\n  export function updateCalls(change) { ... }',styles['CodeDS']),p('<b>Depois</b>'),Preformatted('// attendance.ts\nexport { storageKey, readCalls, updateCalls }\n  from "./modules/attendance/storage"\n\n// storage.ts\n// Mesmas funcoes e chave, sem mudar o algoritmo.',styles['CodeDS']),p('<b>Catálogo:</b> Extract Module / Move Function. A chave permanece frequencia-ufpe:demo:v1. Dados existentes, fallback e erros mantêm o comportamento. A responsabilidade de armazenamento agora tem um ponto específico para evoluir.'),p('<b>Evidência:</b> 50/50 antes (DT-02-depois.txt), 50/50 depois (DT-03-depois.txt). Commit: “DT-03: isola persistencia local e preserva fachada publica”. Nenhuma mudança nos testes; validação de estrutura de JSON não foi adicionada neste passo (DT-07).'),heading('Reflexão e pendências'),p('A inspeção de código com apoio de LLM identificou mistura de responsabilidades e dependência de fixtures; o V8 localizou o caminho sem locks não testado. As abordagens são complementares: a cobertura mede execução, enquanto a inspeção examina responsabilidades. O procedimento e seus limites estão em log-analise.md. A revisão dos integrantes e a atribuição de responsáveis integram o plano de acompanhamento. DT-01/02/03 estão refatorados; DT-04 a DT-08 permanecem abertos.'),p('Os testes protegem somente o escopo medido. Não cobrem UI, autenticação real, backend nem concorrência do navegador. Detalhes, estimativas e casos descartados: divida-tecnica.md e log-analise.md.','SmallDS')]
build(Path('docs/qualidade/relatorio-refatoracao.pdf'),s)
print('PDFs gerados')
